We define $\bot$  to be the label of the  genesis $\rho$. 
Let $\mathcal{Y}$ be a label space such that $\bot\in\mathcal{Y}$, and $\mathrm{label}: \mathcal{L} \to \mathcal{Y}$ be a function with the following properties:
\begin{enumerate}[leftmargin=*]

   \item if $x \in \mathcal{L} \setminus \{ \mathcal{C}\}$, then $\mathrm{label}(x)=\bot$;
    \item the restriction of the function $\mathrm{label}$ on the set $\mathcal{C}\cup \{\rho\}$ is injective, i.e., the image  $\mathrm{label}(\mathcal{C}\cup \{\rho\}):=\{\mathrm{label}(x): x\in \mathcal{C}\cup \{\rho\}\}$ has size $|\mathcal{C}|+1$.  
\end{enumerate}

\caption{Algorithm to update Conflict DAG}

\KwData{Conflict DAG $D_{\mathcal{C}} = (\mathcal{C}\cup \{\rho\}, E)$; new transaction  $x\in \mathcal{L}$ that is directly conflicting with transactions $Y\subseteq \mathcal{L}$}
\KwResult{updated Conflict DAG $D_{\mathcal{C}} = (\mathcal{C}\cup \{\rho\}, E)$}
$\mathcal{C}\gets \mathcal{C}\cup\{x\}\cup Y$ \\

\For{$\forall y\in Y\cup \{x\}$}{
\For{$\forall v\in \mathrm{conf}^{(p)}_{\mathcal{L}}\left(y\right)$}{
$E\gets E\cup \{(y,v)\}$\\
}
\For{$\forall v\in \mathrm{conf}^{(f)}_{\mathcal{L}}\left(y\right)$}{
$E\gets E\cup \{(v,y)\}$
}
}

\For{$\forall y\in Y$}{
\For{$\forall p\in \mathrm{par}_{\mathcal{C}}\left(y\right)$}{
\For{$\forall c\in \mathrm{child}_{\mathcal{C}}\left(p\right)$} {
\If{$c\in \mathrm{cone}_{\mathcal{C}}^{(f)}\left(y\right)$}{
$E\gets E\setminus\{(c,p)\}$
}
}
}
}

\caption{Algorithm to update Conflict Graph}

\KwData{Conflict Graph $G_{\mathcal{C}} = (\mathcal{C}_{old}, E)$; new transaction  $x\in \mathcal{L}$ that is directly conflicting with transactions $Y\subseteq \mathcal{L}$; updated Conflict DAG $D_{\mathcal{C}} = (\mathcal{C}\cup \rho, E)$;}
\KwResult{updated Conflict Graph $G_{\mathcal{C}} = (\mathcal{C}, E)$}
\For{$\forall y\in Y$}{
\For{$\forall z\in \mathrm{cone}_{\mathcal{C}}^{(f)}\left(y\right)$}{
$E\gets E\cup \{(x,z)\}$
}
}


\For{$\forall y\in Y\cup\{x\}$}{
{\scriptsize{\Comment*[l]{assume $D_{\mathcal{C}}$-descending order}}}
\For{$\forall p\in \mathrm{par}_{\mathcal{C}}\left(y\right)$}{
\For{$\forall z\in N_{\mathcal{C}}(p)$}{
{\scriptsize{\Comment*[l]{$N_{\mathcal{C}}(p)$ denotes the set of neighbours of $p$ in $G_{\mathcal{C}}$}}}
$E\gets E\cup \{(y,z)\}$ 
}
}
}

\caption{Reality selection in Branch DAG}

\KwData{Branch DAG $D_{\mathcal{B}} = (\mathcal{B}, E)$}
\KwResult{reality ${R}\in \mathcal{B}$}
${R}\gets \emptyset$ {\scriptsize{\Comment*[r]{{main branch in $D_{\mathcal{B}}$}}}}
\While{${R}$ is not a leaf in $D_{\mathcal{B}}$}{
${B}^* \gets arg\,max\{\mathbf{w}({B}): {B} \in \mathrm{child}_{\mathcal{B}}\left(R\right) \}$ {\scriptsize{\Comment*[r]{use $\min\mathop{\mathrm{hash}}({B}\setminus {R})$ for breaking ties }}}
${R}\gets {B}^*$
}

\caption{Reality selection in Conflict Graph}

\KwData{Conflict Graph $G_{\mathcal{C}}=(\mathcal{C},E)$}
\KwResult{reality ${R}\in \mathcal{B}$}
${R}\gets \emptyset$\\
$U\gets \mathcal{C}$\\
\While{$|U|\neq 0$}{ 
$c^*\gets arg\,max \{ \mathbf{w}(c): c\in \max_{\mathcal{C}}(U)\}$ {\scriptsize{\Comment*[r]{use $\min\mathop{\mathrm{hash}}(c)$ for breaking ties}}}
${R} \gets {R} \cup \{c^*\}$\\ $U \gets U  \setminus \{N_{\mathcal{C}}(c^{*}) \cup\{c^{*}\}\}$
}

\caption{Algorithm to update Ledger DAG, Conflict DAG and Conflict Graph  after branch confirmation}

\KwData{Ledger DAG $D_{\mathcal{L}}=(\mathcal{L},E_{D_{\mathcal{L}}})$, Conflict DAG $D_{\mathcal{C}}=(\mathcal{C}\cup\{\rho\},E_{D_{\mathcal{C}}})$, Conflict Graph $G_{\mathcal{C}} = (\mathcal{C}, E_{G_{\mathcal{C}}})$, confirmed branch ${B}$}
\KwResult{updated Ledger DAG $D_{\mathcal{L}}=(\mathcal{L},E_{D_{\mathcal{L}}})$, Conflict DAG $D_{\mathcal{C}}=(\mathcal{C}\cup\{\rho\},E_{D_{\mathcal{C}}})$, Conflict Graph $G_{\mathcal{C}} = (\mathcal{C}, E_{G_{\mathcal{C}}})$}
$M\gets \min_{\mathcal{C}}({B})$\\
$\mathcal{C}'\gets \emptyset$ {\scriptsize{\Comment*[r]{conflicts conflicting with $B$}}}
$\mathcal{C}''\gets \emptyset$ {\scriptsize{\Comment*[r]{conflicts to be removed from $\mathcal{C}$}}}


\For{$\forall x\in M$}{
\For{$\forall y\in N_{\mathcal{C}}(x)$}{
$\mathcal{C}'\gets \mathcal{C}' \cup \{y\}$\\
\For{$\forall z\in N_{\mathcal{C}}(y)$}{
$E_{G_{\mathcal{C}}}\gets E_{G_{\mathcal{C}}}\setminus\{(y,z)\}$}}}

\For{$\forall x\in \mathcal{C}$}{
\If{$x$ is isolated in $G_{\mathcal{C}}$}{
$\mathcal{C}''\gets \mathcal{C}'' \cup\{x\}$
}
}
\For{$\forall y\in \max_{\mathcal{C}}(\mathcal{C} ')$}{
\For{$\forall z\in \mathrm{cone}_{\mathcal{L}}^{(f)}\left(y\right)$}{
{\scriptsize{\Comment*[l]{assume $D_{\mathcal{L}}$-descending order}}}
$\mathcal{L}\gets \mathcal{L}\setminus\{z\}$\\
\For{$\forall p\in \mathrm{par}_{\mathcal{L}}\left(z\right)$}{
$E_{D_{\mathcal{L}}}\gets E_{D_{\mathcal{L}}} \setminus\{(z,p)\}$
}
}
}
\For{$\forall y\in \mathcal{C} ''$}{
\For{$\forall p\in \mathrm{par}_{\mathcal{C}}\left(y\right)$}{
$E_{D_{\mathcal{C}}}\gets E_{D_{\mathcal{C}}} \setminus\{(y,p)\}$
}
\If{$y\in \max_{\mathcal{C}}(\mathcal{C}'')$}{
\For{$\forall c\in\mathrm{child}_{\mathcal{C}}\left(y\right)$}{
$E_{D_{\mathcal{C}}}\gets E_{D_{\mathcal{C}}} \setminus\{(c,y)\}$\\
\If{$\mathrm{par}_{\mathcal{C}}\left(c\right)\subseteq \mathcal{C}''$}{
$E_{D_{\mathcal{C}}}\gets E_{D_{\mathcal{C}}} \cup\{(c,\rho)\}$
}
}
}
$\mathcal{C} \gets \mathcal{C} \setminus \{y\}$\\
}
